/**
 * Validates if a string is a Nigerian mobile number in the specified formats:
 * 1. 0[7-9][01] followed by 8 digits (Total 11 digits)
 * 2. +234[7-9][01] followed by 8 digits
 * 
 * @param {string} s - The string to validate.
 * @returns {boolean} - True if valid, false otherwise.
 */
function isNigerianMobile(s) {
  const regex = /^(0|\+234)[7-9][01]\d{8}$/;
  return regex.test(s);
}
