function wordCount(text) {
  const counts = {};
  // Convert to lowercase and split by any non-alphabetical character
  // The regex [^a-z]+ matches one or more characters that are NOT a-z
  const words = text.toLowerCase().split(/[^a-z]+/);

  for (const word of words) {
    // Split can produce empty strings if there are leading/trailing non-alpha chars
    if (word.length > 0) {
      counts[word] = (counts[word] || 0) + 1;
    }
  }

  return counts;
}
