function chunk(array, size) {
  if (!Array.isArray(array) || typeof size !== 'number' || size <= 0) {
    return [];
  }

  const chunked = [];
  for (let i = 0; i < array.length; i += size) {
    chunked.push(array.slice(i, i + size));
  }
  return chunked;
}
