function flatten(value) {
  const result = [];

  function recursiveFlatten(item) {
    if (Array.isArray(item)) {
      for (let i = 0; i < item.length; i++) {
        recursiveFlatten(item[i]);
      }
    } else {
      result.push(item);
    }
  }

  recursiveFlatten(value);
  return result;
}
